grey studio design reference; right view' WHERE id='viewfix-20261027-vn-street-switch-right' AND product_id='vn-street-switch' AND image_url='https://api.vantanoir.store/api/media/products/928c162e-aef0-5cbe-84e6-287c054b19ab.webp';UPDATE products SET image_url='https://api.vantanoir.store/api/media/products/df016031-0011-4000-8000-000000000001.webp',updated_at=datetime('now') WHERE id='vn-street-switch' AND image_url='https://api.vantanoir.store/api/media/products/73ab1647-b986-58bc-82e6-c1c039f065bf.webp'; SELECT id,image_url FROM products WHERE id='vn-street-switch'; SELECT image_alt,image_url FROM product_images WHERE product_id='vn-street-switch' ORDER BY sort_order;
